MATCH (head:ProcessInstrumentationFunction {loop_tag: 'LSHH-37002'})-[:send_signal_to*1..]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(v:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (i:PlantItem {tag: 'P-1101'})-[:is_drawn_on]->(s:Sheet)
RETURN i.tag AS tag, s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (item:PlantItem {tag: 'TK-1002'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (a:PlantItem {tag: 'EA-2901'}), (b:PlantItem {tag: 'P-3101'})
RETURN EXISTS {
  MATCH (a)-[r:line_to*1..]->(b)
  WHERE all(n IN nodes(r) WHERE n.tag <> 'V-2901')
} AS reachable

MATCH (item:PlantItem {tag: 'P-1204'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (a:PlantItem {tag: 'EA-2901'}), (b:PlantItem {tag: 'P-3101'})
RETURN EXISTS {
  MATCH (a)-[rels:line_to*1..]->(b)
  WHERE all(rel IN rels WHERE startNode(rel).tag <> 'V-2901' AND endNode(rel).tag <> 'V-2901')
} AS reachable

MATCH (a:PlantItem {tag: 'E-201'}), (b:PlantItem {tag: 'EH-201'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH p = shortestPath((a)-[:line_to*1..]->(b))
         WHERE NONE(n IN nodes(p) WHERE n.tag = 'TV-2044')
       } AS reachable_without_TV_2044

MATCH (v:CheckValve:PlantItem {unit_id: '3'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (r:PlantItem {tag: 'R-1901'}), (e:PlantItem {tag: 'E-1901'}), (v:Valve)
WHERE EXISTS { (r)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(e) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag, tag

MATCH (f:PlantItem:Furnace {unit_id: '11'})
