MATCH (a:PlantItem {tag: 'P-2203'}), (b:PlantItem {tag: 'V-2301'}), (v:Valve)
WHERE v <> a AND v <> b
  AND EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
